#!/usr/bin/env python3
# PB23c 十二带 (生长速度非等距刀) · A 军专镜 · 判据承 23b zoom 律 (主人 0927「做完可再细」令)
import os,json,time,base64,hashlib,copy,random,itertools,gc
os.system("python -m pip uninstall -y -q torchao 2>/dev/null")
import numpy as np,torch
from transformers import AutoTokenizer,AutoModelForCausalLM
from peft import LoraConfig,get_peft_model,TaskType
PAYLOAD={"c1_16-18_train": {"b64": "", "sha256": "9c37c7da9ffa0c17edb4e10673443e1ff3d8a2db5524a2075fead4f9b6918386"}, "c2_19-21_train": {"b64": "", "sha256": "c3bbc8abdc616644842565a22ee0c56600024e5c3727a6a4d8804e7da4172343"}, "c3_22-24_train": {"b64": "", "sha256": "cc6d3cc6121737a816c1ab31e16734c5c23541566dba1edb8295a2b5a84b7717"}, "c4_25-27_train": {"b64": "", "sha256": "dc20c440bc4a9a37ff22088cc2cddd777ef2db7dd6881b40a14947e24d4892e3"}, "c5_28-31_train": {"b64": "", "sha256": "178b62b0f60edc6750c0c3b7db4b0c4da436969dc698de8c70ae216105e2d61b"}, "c6_32-35_train": {"b64": "", "sha256": "3fe3d7d61928d02f0b69b93d30d9f17326868e5b0cb77291558cc4beda1f5662"}, "c7_36-39_train": {"b64": "", "sha256": "ae2ef99d4f391c0082d9672ab85dcd48526451c39cf0c8e7ee07abf9183c68b2"}, "c8_40-44_train": {"b64": "", "sha256": "a620dde8142479a3f4ce7cce236ab62e8a4a8cc5d29a38c3a7cb9839d5d0e6e9"}, "c9_45-49_train": {"b64": "", "sha256": "5d62771ed6ecd200b71540c0a7fc7a4824bfdc9b6ee1ca789adaca4b43bdf42b"}, "c10_50-55_train": {"b64": "", "sha256": "85daa2c83d53579aa30ef945429ba649ac3e4cfae850223be85ef5b2eba99d46"}, "c11_56-62_train": {"b64": "", "sha256": "20b2c1211412686da563b1e8b39de36314d44cc560456be66c5daa2a009c9100"}}
assert all(hashlib.sha256(base64.b64decode(v["b64"])).hexdigest()==v["sha256"] for v in PAYLOAD.values())
DEV="cuda";OUT="/kaggle/working";M="/kaggle/input/models/qwen-lm/qwen2.5/transformers/0.5b-instruct/1"
BANDS=sorted(PAYLOAD.keys())
def load(k): return [json.loads(l) for l in base64.b64decode(PAYLOAD[k]["b64"]).decode().strip().split("\n")]
tok=AutoTokenizer.from_pretrained(M); base=AutoModelForCausalLM.from_pretrained(M,dtype=torch.float16)
def enc(i):
    u,a=i["messages"][0]["content"],i["messages"][1]["content"]
    pre=tok.apply_chat_template([{"role":"user","content":u},{"role":"assistant","content":""}],tokenize=False,add_generation_prompt=True)
    full=tok.apply_chat_template(i["messages"],tokenize=False)
    fi=tok(full,add_special_tokens=False)["input_ids"];pi=tok(pre,add_special_tokens=False)["input_ids"]
    if len(pi)>=len(fi) or not a: return None
    return fi,[-100]*len(pi)+fi[len(pi):]
def build():
    global m
    m=get_peft_model(copy.deepcopy(base),LoraConfig(task_type=TaskType.CAUSAL_LM,r=16,lora_alpha=32,lora_dropout=0.05,bias="none",
      target_modules=["q_proj","k_proj","v_proj","o_proj","gate_proj","up_proj","down_proj"])).to(DEV)
build()
def reset(sd):
    torch.manual_seed(sd);random.seed(sd)
    for mod in m.modules():
        for md in getattr(mod,'lora_A',{}).values(): md.reset_parameters()
        for md in getattr(mod,'lora_B',{}).values(): torch.nn.init.zeros_(md.weight)
    for prm in m.parameters(): prm.grad=None
def one(k,sd):
    reset(sd)
    opt=torch.optim.AdamW([q for q in m.parameters() if q.requires_grad],lr=1e-4);m.train()
    p=[x for x in (enc(i) for i in load(k)) if x]
    for e in range(4):
        o=list(range(len(p)));random.shuffle(o)
        for j,ix in enumerate(o,1):
            fi,la=p[ix]
            l=m(input_ids=torch.tensor([fi],device=DEV),labels=torch.tensor([la],device=DEV)).loss/4
            l.backward()
            if j%4==0 or j==len(o):opt.step();opt.zero_grad()
    g={}
    for n,pp in m.named_parameters():
        if ".lora_" in n:
            b=n.split(".lora_")[0];kd=n.split(".lora_")[1][0];g.setdefault(b,{})[kd]=pp.detach().cpu().float().numpy().copy()
    U={}
    for b,d in g.items():
        U_,sv,Vt=np.linalg.svd(d["B"]@d["A"],full_matrices=False);U[b]=U_[:,:8]
    return U
def ov(A,B):
    vs=[]
    for b in A:
        if b in B:
            k=min(A[b].shape[1],B[b].shape[1]);vs.append(np.linalg.norm(A[b][:,:k].T@B[b][:,:k],"fro")/np.sqrt(k))
    return round(float(np.mean(vs)),4) if vs else None
REP={"case":"PB23c","bands":BANDS,"runs":[]}
def fl(t):
    REP["_meta"]={"stage":t,"t":time.strftime("%H:%M:%S")}
    json.dump(REP,open(f"{OUT}/report_pb23c.json","w"),ensure_ascii=False)
    print("REPORT_LINE::"+base64.b64encode(json.dumps(REP).encode()).decode()[:3800],flush=True)
S={}
for sd in [13,14,15]:
    for k in BANDS: S[(k,sd)]=one(k,sd);fl(f"{k}s{sd}")
def bn(k): return int(k[1:k.index("_")])
for x,y in itertools.combinations(BANDS,2):
    REP["runs"].append({"pair":f"{x}~{y}","dist":abs(bn(x)-bn(y)),"ov":[ov(S[(x,s)],S[(y,s)]) for s in [13,14,15]]})
fl("pairs")
D={}
for r in REP["runs"]: D.setdefault(r["dist"],[]).extend(r["ov"])
med={d:round(float(np.median(D[d])),4) for d in sorted(D)}
near=[v for dd,v in sorted(med.items())][:3];far=[v for dd,v in sorted(med.items())][-3:]
REP["verdict"]={"dist_median":med,"trend":"下沉" if np.polyfit(list(med),list(med.values()),1)[0]<-0.004 else ("平线" if abs(np.polyfit(list(med),list(med.values()),1)[0])<=0.004 else "反常"),"zoom_再细令":"膝在则廿四带; 平线则此系终镜","sentinel":"pb23c_ok"}
fl("final");print("DONE PB23c",json.dumps(REP["verdict"],ensure_ascii=False)[:300])